package com.bank.builder;

import java.math.BigDecimal;
import java.util.logging.Logger;

class Order {                                  // immutable product
    private final String id, symbol, side;
    private final int quantity; private final BigDecimal price;

    private Order(Builder b) {                 // only the builder can construct
        this.id = b.id; this.symbol = b.symbol; this.quantity = b.quantity;
        this.price = b.price; this.side = b.side;
    }
    static Builder builder(String id, String symbol) { return new Builder(id, symbol); }
    public String toString() { return side + " " + quantity + " " + symbol + " @ " + price + " [" + id + "]"; }

    static class Builder {
        private final String id, symbol;       // required fields in builder ctor
        private int quantity; private BigDecimal price; private String side = "BUY";
        Builder(String id, String symbol) { this.id = id; this.symbol = symbol; }
        Builder quantity(int q) { this.quantity = q; return this; }  // fluent
        Builder price(BigDecimal p) { this.price = p; return this; }
        Builder side(String s) { this.side = s; return this; }
        Order build() {                         // validate invariants here
            if (quantity <= 0) throw new IllegalArgumentException("quantity must be positive");
            if (price == null || price.signum() <= 0) throw new IllegalArgumentException("price must be positive");
            return new Order(this);
        }
    }
}

public class BuilderDemo {
    public static void main(String[] args) {
        Logger log = Logger.getLogger("ORDER");
        Order rajeshOrder = Order.builder("ORD-1", "RELIANCE")
                .quantity(100).price(new BigDecimal("2450")).side("BUY").build();
        log.info("Built: " + rajeshOrder);
        try {
            Order.builder("ORD-2", "TCS").quantity(-5).price(new BigDecimal("3000")).build();
        } catch (IllegalArgumentException e) {
            log.severe("Rejected invalid order: " + e.getMessage());
        }
    }
}
